import "core-js/modules/es.array.push.js";
import "core-js/modules/esnext.iterator.constructor.js";
import "core-js/modules/esnext.iterator.filter.js";
import "core-js/modules/esnext.iterator.for-each.js";
import "core-js/modules/esnext.iterator.map.js";
import { ref, onMounted } from 'vue';
import { collection, query, orderBy, limit, getDocs } from 'firebase/firestore';
import { db } from '../firebase';
import { useRouter } from 'vue-router';
import AdminNavigationBar from './AdminNavigationBar.vue';
const defaultAvatar = "https://ui-avatars.com/api/?background=0F2942&color=fff";

// Invitation Analytics State

export default {
  __name: 'Admin_Dashboard',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const router = useRouter();
    const loading = ref(true);
    const invitationLoading = ref(true);
    const refreshing = ref(false);
    const showMaintenance = ref(false);
    const maintenanceMessage = ref('');
    const maintenanceDuration = ref('');
    const totalInvitations = ref(0);
    const activeInvitations = ref(0);
    const archivedInvitations = ref(0);
    const expiredInvitations = ref(0);
    const fetchInvitationAnalytics = async () => {
      invitationLoading.value = true;
      try {
        const invitationsRef = collection(db, "invitations");
        const snapshot = await getDocs(invitationsRef);
        let total = 0;
        let active = 0;
        let archived = 0;
        let expired = 0;
        const now = new Date();
        snapshot.forEach(doc => {
          const data = doc.data();
          total++;
          if (data.status === "Active" || data.status === "active") {
            active++;
          }
          if (data.status === "Archived" || data.status === "archived") {
            archived++;
          }
          if (data.expiryDate) {
            let expiry;
            if (typeof data.expiryDate === "string") {
              expiry = new Date(data.expiryDate);
            } else if (data.expiryDate.toDate) {
              expiry = data.expiryDate.toDate();
            }
            if (expiry && expiry < now) {
              expired++;
            }
          }
          if (data.expirationDate && data.expirationDate.toDate && data.expirationDate.toDate() < now) {
            expired++;
          }
        });
        totalInvitations.value = total;
        activeInvitations.value = active;
        archivedInvitations.value = archived;
        expiredInvitations.value = expired;
      } catch (error) {
        console.error("Error fetching invitations:", error);
      }
      invitationLoading.value = false;
    };

    // Fix: define missing refs for dashboard data
    const recentUsers = ref([]);
    const stats = ref({
      totalUsers: 0,
      activeUsers: 0,
      newUsers: 0,
      userGrowth: 0,
      systemHealth: 98
    });
    const recentLogs = ref([]);

    // Upcoming Deadlines Analytics State
    const upcomingDeadlines = ref([]);
    const upcomingDeadlinesLoading = ref(true);
    const fetchUpcomingDeadlines = async () => {
      upcomingDeadlinesLoading.value = true;
      try {
        const invitationsRef = collection(db, "invitations");
        const snapshot = await getDocs(invitationsRef);
        const now = new Date();
        const upcoming = [];
        snapshot.forEach(doc => {
          const data = doc.data();
          let expiry;
          if (data.expiryDate) {
            if (typeof data.expiryDate === "string") {
              expiry = new Date(data.expiryDate);
            } else if (data.expiryDate.toDate) {
              expiry = data.expiryDate.toDate();
            }
          } else if (data.expirationDate && data.expirationDate.toDate) {
            expiry = data.expirationDate.toDate();
          }
          if (expiry && expiry > now) {
            upcoming.push({
              id: doc.id,
              title: data.title || "Untitled Invitation",
              expiry,
              status: data.status || "Unknown"
            });
          }
        });
        // Sort by soonest deadline
        upcoming.sort((a, b) => a.expiry - b.expiry);
        upcomingDeadlines.value = upcoming;
      } catch (error) {
        console.error("Error fetching upcoming deadlines:", error);
      }
      upcomingDeadlinesLoading.value = false;
    };

    // Load existing code
    onMounted(async () => {
      try {
        await Promise.all([loadDashboardData(), fetchInvitationAnalytics(), fetchUpcomingDeadlines()]);
      } finally {
        loading.value = false;
      }
    });
    const loadDashboardData = async () => {
      try {
        // Fetch users
        const usersQuery = query(collection(db, 'users'), orderBy('createdAt', 'desc'), limit(5));
        const usersSnapshot = await getDocs(usersQuery);
        recentUsers.value = usersSnapshot.docs.map(doc => ({
          id: doc.id,
          name: doc.data().username || 'Unknown User',
          email: doc.data().email,
          avatar: doc.data().profileImageUrl,
          status: doc.data().status || 'active',
          createdAt: doc.data().createdAt
        }));

        // Calculate stats
        stats.value = {
          totalUsers: usersSnapshot.size,
          activeUsers: recentUsers.value.filter(u => u.status === 'active').length,
          newUsers: recentUsers.value.filter(u => {
            const created = new Date(u.createdAt);
            return Date.now() - created < 24 * 60 * 60 * 1000;
          }).length,
          userGrowth: 5.2,
          // Example value
          systemHealth: 98
        };

        // Fetch logs
        const logsQuery = query(collection(db, 'system_logs'), orderBy('timestamp', 'desc'), limit(5));
        const logsSnapshot = await getDocs(logsQuery);
        recentLogs.value = logsSnapshot.docs.map(doc => ({
          id: doc.id,
          ...doc.data()
        }));

        // If no logs exist yet, add some sample logs
        if (recentLogs.value.length === 0) {
          recentLogs.value = [{
            id: '1',
            type: 'info',
            message: 'System startup completed',
            timestamp: new Date().getTime()
          }, {
            id: '2',
            type: 'success',
            message: 'Database backup successful',
            timestamp: new Date().getTime() - 3600000
          }, {
            id: '3',
            type: 'warning',
            message: 'High server load detected',
            timestamp: new Date().getTime() - 7200000
          }];
        }
      } catch (error) {
        console.error('Error loading dashboard data:', error);
      }
    };

    // Utility functions
    const getHealthStatus = health => {
      if (health >= 90) return 'excellent';
      if (health >= 70) return 'good';
      if (health >= 50) return 'fair';
      return 'poor';
    };
    const formatTime = timestamp => {
      if (!timestamp) return 'Unknown';
      const date = new Date(timestamp);
      const now = new Date();
      const diffTime = Math.abs(now - date);
      const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays === 0) {
        const diffHours = Math.floor(diffTime / (1000 * 60 * 60));
        if (diffHours === 0) {
          const diffMinutes = Math.floor(diffTime / (1000 * 60));
          return `${diffMinutes} minute${diffMinutes !== 1 ? 's' : ''} ago`;
        }
        return `${diffHours} hour${diffHours !== 1 ? 's' : ''} ago`;
      } else if (diffDays < 7) {
        return `${diffDays} day${diffDays !== 1 ? 's' : ''} ago`;
      } else {
        return date.toLocaleDateString();
      }
    };

    // Action handlers
    const refreshStats = async () => {
      refreshing.value = true;
      try {
        await loadDashboardData();
      } finally {
        setTimeout(() => {
          refreshing.value = false;
        }, 1000);
      }
    };
    const backupSystem = () => {
      alert('System backup initiated');
    };
    const clearCache = () => {
      alert('Cache cleared successfully');
    };
    const generateReport = () => {
      alert('Report generation started');
    };
    const showMaintenanceModal = () => {
      showMaintenance.value = true;
    };
    const enableMaintenance = async () => {
      alert(`Maintenance mode enabled for ${maintenanceDuration.value} minutes with message: ${maintenanceMessage.value}`);
      showMaintenance.value = false;
      maintenanceMessage.value = '';
      maintenanceDuration.value = '';
    };
    const navigateTo = route => {
      router.push(`/${route}`);
    };
    const __returned__ = {
      router,
      loading,
      invitationLoading,
      refreshing,
      showMaintenance,
      maintenanceMessage,
      maintenanceDuration,
      defaultAvatar,
      totalInvitations,
      activeInvitations,
      archivedInvitations,
      expiredInvitations,
      fetchInvitationAnalytics,
      recentUsers,
      stats,
      recentLogs,
      upcomingDeadlines,
      upcomingDeadlinesLoading,
      fetchUpcomingDeadlines,
      loadDashboardData,
      getHealthStatus,
      formatTime,
      refreshStats,
      backupSystem,
      clearCache,
      generateReport,
      showMaintenanceModal,
      enableMaintenance,
      navigateTo,
      ref,
      onMounted,
      get collection() {
        return collection;
      },
      get query() {
        return query;
      },
      get orderBy() {
        return orderBy;
      },
      get limit() {
        return limit;
      },
      get getDocs() {
        return getDocs;
      },
      get db() {
        return db;
      },
      get useRouter() {
        return useRouter;
      },
      AdminNavigationBar
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
